def queen_attacks_from(pos, n):
    x0, y0 = pos
    a = set([pos])    
    a.update((x, y0) for x in range(n))    
    a.update((x0, y) for y in range(n))    

    for x1 in range(n):

        y1 = y0 -x0 +x1
        if 0 <= y1 < n: 
            a.add((x1, y1))

        y1 = y0 +x0 -x1
        if 0 <= y1 < n: 
            a.add((x1, y1))
    return a

